     1	// Opening hours and slots of the meeting rooms. Times are minutes from midnight.
     2	export const OPEN_HOUR = 8;
     3	export const CLOSE_HOUR = 20;
     4	
     5	// "2026-03-04 09:00-10:30" -> { day: '2026-03-04', start: 540, end: 630 }
     6	export function parseSlot(text) {
     7	  const m = /^(\d{4}-\d{2}-\d{2}) (\d{2}):(\d{2})-(\d{2}):(\d{2})$/.exec(String(text).trim());
     8	  if (!m) throw new Error(`not a slot: ${text}`);
     9	  const start = Number(m[2]) * 60 + Number(m[3]);
    10	  const end = Number(m[4]) * 60 + Number(m[5]);
    11	  if (end <= start) throw new Error('a slot must end after it starts');
    12	  if (start < OPEN_HOUR * 60 || end > CLOSE_HOUR * 60) throw new Error('outside opening hours');
    13	  return { day: m[1], start, end };
    14	}
    15	
    16	export function formatSlot({ day, start, end }) {
    17	  const hm = (t) => `${String(Math.floor(t / 60)).padStart(2, '0')}:${String(t % 60).padStart(2, '0')}`;
    18	  return `${day} ${hm(start)}-${hm(end)}`;
    19	}
    20	
    21	export function overlaps(a, b) {
    22	  return a.day === b.day && a.start < b.end && b.start < a.end;
    23	}
=== src/waitlist.js
     1	// Waitlist for slots that are already taken (#21). When a booking is cancelled, its slot is offered to the
     2	// first person who waits for that room at an overlapping time. The offer holds for 30 minutes.
     3	import { overlaps, parseSlot } from './slots.js';
     4	
     5	export const OFFER_MINUTES = 30;
     6	
     7	export function createWaitlist() {
     8	  return { entries: [], seq: 1 };
     9	}
    10	
    11	// Join the waitlist. A person waits at most once for the same room and slot.
    12	export function join(list, { person, room, slot }) {
    13	  if (!person) throw new Error('person is required');
    14	  const s = parseSlot(slot);
    15	  const same = (e) => e.person === person && e.room === room && e.day === s.day && e.start === s.start && e.end === s.end;
    16	  if (list.entries.some(same)) return { ok: false, reason: 'already waiting' };
    17	  list.entries.push({ seq: list.seq++, person, room, ...s });
    18	  return { ok: true, position: waitingFor(list, room, s).length };
    19	}
    20	
    21	// Leave the waitlist for a room. Returns whether the person was waiting.
    22	export function leave(list, person, room) {
    23	  const before = list.entries.length;
    24	  list.entries = list.entries.filter((e) => !(e.person === person && e.room === room));
    25	  return list.entries.length < before;
    26	}
    27	
    28	// Everyone waiting for the room at a time that overlaps the slot, first come first.
    29	export function waitingFor(list, room, slot) {
    30	  return list.entries.filter((e) => e.room === room && overlaps(e, slot)).sort((a, b) => a.seq - b.seq);
    31	}
    32	
    33	// A booking was cancelled: offer its slot to the first person waiting, and take that entry off the waitlist
    34	// (the person joins again if they decline the offer).
    35	export function offerFreedSlot(list, cancelled, now = Date.now()) {
    36	  const [first] = waitingFor(list, cancelled.room, cancelled);
    37	  if (!first) return null;
    38	  return {
    39	    to: first.person,
    40	    room: cancelled.room,
    41	    day: cancelled.day,
    42	    start: cancelled.start,
    43	    end: cancelled.end,
    44	    expiresAt: now + OFFER_MINUTES * 60_000,
    45	  };
    46	}
    47	
    48	// How many people wait, per room.
    49	export function countsByRoom(list) {
    50	  const counts = {};
    51	  for (const e of list.entries) counts[e.room] = (counts[e.room] ?? 0) + 1;
    52	  return counts;
    53	}
