import { test } from 'node:test';
import assert from 'node:assert/strict';
import { book, cancel, createBook } from '../src/bookings.js';
import { countsByRoom, createWaitlist, join, leave, offerFreedSlot, waitingFor } from '../src/waitlist.js';

// A booking that was made and then cancelled, the way bookings.js hands it over.
function cancelledBooking(room, slot) {
  const store = createBook();
  const { booking } = book(store, { room, slot, person: 'aya' });
  return cancel(store, booking.id);
}

test('the first person to join waits in position 1', () => {
  const list = createWaitlist();
  assert.deepEqual(join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' }), { ok: true, position: 1 });
});

test('nobody joins without a name', () => {
  const list = createWaitlist();
  assert.throws(() => join(list, { person: '', room: 'small', slot: '2026-03-04 09:00-10:00' }), /person is required/);
  assert.deepEqual(list.entries, []);
});

test('a person waits at most once for the same room and slot', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' });
  assert.deepEqual(join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' }), { ok: false, reason: 'already waiting' });
  assert.deepEqual(list.entries.map((e) => e.person), ['mio']);
});

test('the same person may wait for another room, another day or another time', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' });
  assert.equal(join(list, { person: 'mio', room: 'large', slot: '2026-03-04 09:00-10:00' }).ok, true);
  assert.equal(join(list, { person: 'mio', room: 'small', slot: '2026-03-05 09:00-10:00' }).ok, true);
  assert.equal(join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:30-10:00' }).ok, true);
  assert.equal(join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-09:30' }).ok, true);
  assert.equal(list.entries.length, 5);
});

test('a later person queues behind those who wait for the room at an overlapping time', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' });
  assert.deepEqual(join(list, { person: 'ken', room: 'small', slot: '2026-03-04 09:30-10:30' }), { ok: true, position: 2 });
  assert.deepEqual(join(list, { person: 'rin', room: 'large', slot: '2026-03-04 09:00-10:00' }), { ok: true, position: 1 });
  assert.deepEqual(join(list, { person: 'sora', room: 'small', slot: '2026-03-04 10:30-11:00' }), { ok: true, position: 2 });
  assert.deepEqual(join(list, { person: 'yui', room: 'small', slot: '2026-03-04 13:00-14:00' }), { ok: true, position: 1 });
});

test('the people waiting for a slot are listed first come first, for that room and time only', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:30-10:30' });
  join(list, { person: 'rin', room: 'large', slot: '2026-03-04 09:00-10:00' });
  join(list, { person: 'yui', room: 'small', slot: '2026-03-04 10:00-11:00' });
  join(list, { person: 'sora', room: 'small', slot: '2026-03-05 09:00-10:00' });
  join(list, { person: 'ken', room: 'small', slot: '2026-03-04 09:00-10:00' });
  const slot = { day: '2026-03-04', start: 540, end: 600 };
  assert.deepEqual(waitingFor(list, 'small', slot).map((e) => e.person), ['mio', 'ken']);
});

test('leaving takes the person off the waitlist of that room only', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' });
  join(list, { person: 'mio', room: 'large', slot: '2026-03-04 09:00-10:00' });
  join(list, { person: 'ken', room: 'small', slot: '2026-03-04 09:00-10:00' });
  assert.equal(leave(list, 'mio', 'small'), true);
  assert.deepEqual(list.entries.map((e) => [e.person, e.room]), [['mio', 'large'], ['ken', 'small']]);
});

test('leaving tells when the person was not waiting for the room', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'large', slot: '2026-03-04 09:00-10:00' });
  assert.equal(leave(list, 'mio', 'small'), false);
  assert.equal(leave(list, 'ken', 'large'), false);
  assert.deepEqual(list.entries.map((e) => [e.person, e.room]), [['mio', 'large']]);
});

test('a freed slot is offered for 30 minutes to the first person waiting for that room and time', () => {
  const list = createWaitlist();
  join(list, { person: 'rin', room: 'large', slot: '2026-03-04 09:00-10:00' });
  join(list, { person: 'yui', room: 'small', slot: '2026-03-04 10:00-11:00' });
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:30-10:30' });
  join(list, { person: 'ken', room: 'small', slot: '2026-03-04 09:00-10:00' });
  const offer = offerFreedSlot(list, cancelledBooking('small', '2026-03-04 09:00-10:00'), 1_000_000);
  assert.deepEqual(offer, { to: 'mio', room: 'small', day: '2026-03-04', start: 540, end: 600, expiresAt: 2_800_000 });
});

test('an offer made without a time holds for 30 minutes from now', () => {
  const list = createWaitlist();
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' });
  const before = Date.now();
  const offer = offerFreedSlot(list, cancelledBooking('small', '2026-03-04 09:00-10:00'));
  const after = Date.now();
  assert.ok(offer.expiresAt >= before + 1_800_000 && offer.expiresAt <= after + 1_800_000, `expiresAt ${offer.expiresAt} is not 30 minutes after ${before}..${after}`);
});

test('a freed slot is offered to nobody when nobody waits for it', () => {
  const list = createWaitlist();
  join(list, { person: 'rin', room: 'large', slot: '2026-03-04 09:00-10:00' });
  join(list, { person: 'yui', room: 'small', slot: '2026-03-04 10:00-11:00' });
  assert.equal(offerFreedSlot(list, cancelledBooking('small', '2026-03-04 09:00-10:00'), 1_000_000), null);
});

test('the people waiting are counted per room', () => {
  const list = createWaitlist();
  assert.deepEqual(countsByRoom(list), {});
  join(list, { person: 'mio', room: 'small', slot: '2026-03-04 09:00-10:00' });
  join(list, { person: 'ken', room: 'small', slot: '2026-03-04 13:00-14:00' });
  join(list, { person: 'rin', room: 'large', slot: '2026-03-04 09:00-10:00' });
  assert.deepEqual(countsByRoom(list), { small: 2, large: 1 });
});

